function prepareRequest(body, from) {
  const name = typeof body?.name === "string" ? body.name.trim() : "";
  const number = typeof body?.number === "string" ? body.number.trim() : "";
  const city = typeof body?.city === "string" ? body.city.trim() : "";
  const phone = /^\+[1-9]\d{6,14}$/;
  if (
    !name ||
    name.length > 120 ||
    !city ||
    city.length > 180 ||
    /[\x00-\x1f\x7f]/.test(name + city) ||
    !phone.test(number)
  ) {
    throw new Error(
      "Send nonempty name and city strings and an international phone number in E.164 format",
    );
  }
  if (typeof from !== "string" || !phone.test(from))
    throw new Error("Configure an SMS-capable Twilio number in E.164 format");
  return { fields: { Name: name, Number: number, City: city }, from };
}

const twilioNumber = "YOUR_TWILIO_NUMBER";
const enableWrites = false;
if (!enableWrites)
  throw new Error("Configure and verify Webhook Header authentication before enabling writes");
const { fields, from } = prepareRequest($input.first().json.body, twilioNumber);
return [{ json: { ...fields, from } }];

function verifyWeatherRow(record, expected) {
  if (
    typeof record?.id !== "string" ||
    !/^rec[a-zA-Z0-9]+$/.test(record.id) ||
    record.fields?.Name !== expected.Name ||
    record.fields?.Number !== expected.Number ||
    record.fields?.City !== expected.City
  ) {
    throw new Error("Airtable did not confirm the new row for this request");
  }
  return record.id;
}

const fields = $("Validate the name, number, and city").first().json;
const rows = $input.all();
if (rows.length !== 1) throw new Error("Airtable did not return one new record");
const recordId = verifyWeatherRow(rows[0].json, fields);
return [{ json: { recordId, city: fields.City, to: fields.Number, from: fields.from } }];

function weatherMessage(weather, query) {
  const { name, sys, main, wind } = weather ?? {};
  const description = weather?.weather?.[0]?.description;
  const country = typeof sys?.country === "string" ? sys.country : "";
  const parts = query.split(",");
  const qualifier = parts.at(-1)?.trim() ?? "";
  if (
    (weather?.cod !== 200 && weather?.cod !== "200") ||
    typeof name !== "string" ||
    !name.trim() ||
    !/^[A-Z]{2}$/.test(country) ||
    (parts.length > 1 && /^[a-z]{2}$/i.test(qualifier) && qualifier.toUpperCase() !== country) ||
    typeof description !== "string" ||
    !description.trim() ||
    !Number.isFinite(main?.temp) ||
    !Number.isFinite(main?.humidity) ||
    main.humidity < 0 ||
    main.humidity > 100 ||
    !Number.isFinite(wind?.speed) ||
    wind.speed < 0
  ) {
    throw new Error("OpenWeather did not confirm complete metric weather for the requested city");
  }
  return (
    "The weather in " +
    name +
    ", " +
    country +
    " is " +
    main.temp +
    " °C with " +
    description +
    ". Humidity is " +
    main.humidity +
    "% and wind speed is " +
    wind.speed +
    " m/s."
  );
}

const entry = $("Confirm the saved request").first().json;
return [{ json: { ...entry, body: weatherMessage($input.first().json, entry.city) } }];

function verifySmsReceipt(sms, expected) {
  if (
    typeof sms?.sid !== "string" ||
    !/^SM[0-9a-f]{32}$/i.test(sms.sid) ||
    !["accepted", "queued", "sending", "sent", "delivered"].includes(sms.status) ||
    sms.to !== expected.to ||
    sms.from !== expected.from ||
    sms.body !== expected.body
  ) {
    throw new Error(
      "Twilio did not confirm submission to the requested number. Review Twilio before replaying.",
    );
  }
  return { messageSid: sms.sid, status: sms.status };
}

const request = $("Format the weather text").first().json;
const sms = $input.first().json;
const result = verifySmsReceipt(sms, request);
return [{ json: { recordId: request.recordId, ...result } }];
